export interface PricingPlan {
  id: string;
  name: string;
  amount: number;
  cadence: string;
  description: string;
  features: string[];
  badge?: string;
  featured?: boolean;
  actionLabel?: string;
  href?: string;
}
export interface Pricing01Props {
  eyebrow?: string;
  title?: string;
  description?: string;
  plans?: PricingPlan[];
  currency?: string;
  locale?: string;
  note?: string;
  helperLabel?: string;
  helperHref?: string;
}
export const defaultPlans: PricingPlan[] = [
  {
    id: "monthly",
    name: "Monthly",
    amount: 24.99,
    cadence: "per month",
    description: "A flexible starting point for your next chapter.",
    features: [
      "Guided practice",
      "Tutor conversations",
      "Personal study sessions",
      "Monthly billing",
    ],
    actionLabel: "Choose monthly",
  },
  {
    id: "study-pass",
    name: "Study pass",
    amount: 140,
    cadence: "one-off",
    description: "A full study season. One payment, a clear plan.",
    badge: "ONE-OFF PAYMENT",
    featured: true,
    features: [
      "Everything in Monthly",
      "Extended study access",
      "Progress insights",
      "No automatic renewal",
    ],
    actionLabel: "Choose study pass",
  },
  {
    id: "extended",
    name: "Extended pass",
    amount: 250,
    cadence: "one-off",
    description: "More time to build understanding and confidence.",
    badge: "LONGER ACCESS",
    featured: true,
    features: [
      "Everything in Study pass",
      "Longer study access",
      "Flexible learning pace",
      "No automatic renewal",
    ],
    actionLabel: "Choose extended pass",
  },
];
export function validatePlans(plans: PricingPlan[]): PricingPlan[] {
  const ids = new Set<string>();
  for (const plan of plans) {
    if (!plan.id.trim() || ids.has(plan.id))
      throw new Error("Pricing plans need unique non-empty IDs.");
    if (!Number.isFinite(plan.amount) || plan.amount < 0)
      throw new Error("Pricing amounts must be finite and non-negative.");
    ids.add(plan.id);
  }
  return plans;
}

.pricing01 {
  padding: var(--website-section-padding) var(--container-padding-lg);
  color: var(--text-primary);
  background: var(--background-primary);
}
.pricing01 *,
.pricing01 *::before,
.pricing01 *::after {
  box-sizing: border-box;
}
.pricing01-inner {
  max-width: var(--container-max-width);
  margin-inline: auto;
}
.pricing01 :is(h2, h3, p) {
  margin: 0;
}
.pricing01 .pricing01-intro {
  gap: var(--space-4);
  text-align: center;
  margin-block-end: var(--space-10);
}
.pricing01 .pricing01-intro h2 {
  font-size: var(--website-title-size);
  line-height: var(--line-height-tight);
  letter-spacing: var(--letter-spacing-tighter);
  text-wrap: balance;
}
.pricing01 .pricing01-intro p {
  max-width: var(--content-width-narrow);
}
.pricing01 .pricing01-eyebrow {
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-widest);
  font-weight: var(--font-weight-semibold);
}
.pricing01 .pricing01-cards {
  gap: var(--pricing-card-gap);
}
.pricing01 .pricing01-card {
  flex: 1 1 0;
  min-width: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.pricing01 .pricing01-featured {
  background: var(--pricing-featured-surface);
  color: var(--pricing-featured-text);
}
.pricing01-ribbon {
  padding: var(--space-3) var(--space-4);
  background: var(--surface-raised);
  color: var(--text-primary);
  text-align: center;
  font-size: var(--typography-micro-size);
  font-weight: var(--font-weight-semibold);
  letter-spacing: var(--letter-spacing-widest);
}
.pricing01-ribbon-empty {
  visibility: hidden;
}
.pricing01 .pricing01-body {
  flex: 1;
  gap: var(--space-6);
  padding: var(--pricing-card-padding);
}
.pricing01 .pricing01-summary {
  min-height: calc(var(--space-4) * 10);
  gap: var(--space-4);
}
.pricing01 .pricing01-summary h3 {
  font-size: var(--typography-label-size);
  letter-spacing: var(--letter-spacing-wide);
}
.pricing01 .pricing01-summary p,
.pricing01 .pricing01-summary .text-primary {
  color: inherit;
  font-size: var(--website-copy-size);
  line-height: var(--line-height-relaxed);
}
.pricing01 .pricing01-featured :is(h3, .price) {
  color: inherit;
}
.pricing01-features {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  padding: var(--space-5) 0 0;
  margin: 0;
  list-style: none;
  border-block-start: var(--border-width-thin) solid
    color-mix(in srgb, currentColor 20%, transparent);
}
.pricing01-features li {
  display: flex;
  align-items: start;
  gap: var(--space-3);
  font-size: var(--website-copy-size);
  line-height: var(--line-height-relaxed);
}
.pricing01-check {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  flex: 0 0 var(--space-5);
  height: var(--space-5);
  border-radius: var(--radius-full);
  background: var(--surface-raised);
  color: var(--text-primary);
  font-size: var(--typography-micro-size);
}
.pricing01 .pricing01-action {
  margin-block-start: auto;
  padding-block-start: var(--space-8);
}
.pricing01-action > .btn {
  width: 100%;
  white-space: normal;
  text-align: center;
}
.pricing01 .pricing01-notes {
  margin-block-start: var(--space-6);
  gap: var(--space-4);
  text-align: center;
  font-size: var(--typography-caption-size);
}
.pricing01-notes a {
  color: var(--text-primary);
  text-underline-offset: var(--space-1);
}
.pricing01 a:focus-visible {
  outline: var(--focus-ring-width) solid var(--focus-ring-color);
  outline-offset: var(--focus-ring-offset);
}
@media (max-width: 900px) {
  .pricing01 {
    padding-inline: var(--container-padding);
  }
  .pricing01 .pricing01-cards {
    flex-wrap: wrap;
  }
  .pricing01 .pricing01-card {
    flex-basis: calc(50% - var(--pricing-card-gap));
  }
}
@media (max-width: 600px) {
  .pricing01 .pricing01-cards {
    flex-direction: column;
  }
  .pricing01 .pricing01-card {
    flex-basis: auto;
    width: 100%;
  }
  .pricing01 .pricing01-summary {
    min-height: 0;
  }
}

import { useId } from "react";
import { Button, Card, Flex, Heading, Price, Text } from "@paraxe/react";
import {
  defaultPlans,
  validatePlans,
  type Pricing01Props,
} from "../shared/types";
import "../shared/style.css";
export function Pricing01({
  eyebrow = "YOUR NEXT CHAPTER",
  title = "Choose how to get started.",
  description = "A little structure. A lot of possibility. Find the plan that fits.",
  plans = defaultPlans,
  currency = "GBP",
  locale = "en-GB",
  note = "Illustrative plans. Connect your checkout to enable purchases.",
  helperLabel = "Someone else is paying?",
  helperHref,
}: Pricing01Props) {
  const id = useId();
  return (
    <section className="pricing01" aria-labelledby={id}>
      <div className="pricing01-inner">
        <Flex className="pricing01-intro" direction="column" align="center">
          <Text className="pricing01-eyebrow">{eyebrow}</Text>
          <Heading id={id} level="h2">
            {title}
          </Heading>
          <Text tone="muted">{description}</Text>
        </Flex>
        <Flex className="pricing01-cards" align="stretch" fullWidth>
          {validatePlans(plans).map((plan) => (
            <Card
              as="article"
              key={plan.id}
              className={`pricing01-card${plan.featured ? " pricing01-featured" : ""}`}
            >
              <div
                className={`pricing01-ribbon${plan.badge ? "" : " pricing01-ribbon-empty"}`}
              >
                {plan.badge || "PLAN"}
              </div>
              <Flex className="pricing01-body" direction="column">
                <Flex className="pricing01-summary" direction="column">
                  <Heading level="h3">{plan.name}</Heading>
                  <Flex align="baseline" wrap>
                    <Price
                      amount={plan.amount}
                      currency={currency}
                      locale={locale}
                      size="display"
                    />
                    <Text as="span">{plan.cadence}</Text>
                  </Flex>
                  <Text>{plan.description}</Text>
                </Flex>
                <ul className="pricing01-features">
                  {plan.features.map((feature, i) => (
                    <li key={i}>
                      <span className="pricing01-check" aria-hidden="true">
                        ✓
                      </span>
                      <span>{feature}</span>
                    </li>
                  ))}
                </ul>
                <div className="pricing01-action">
                  {plan.href ? (
                    <a
                      className="btn btn-secondary btn-md"
                      href={plan.href}
                      aria-label={`${plan.actionLabel ?? "Choose plan"}: ${plan.name}`}
                    >
                      {plan.actionLabel ?? "Choose plan"}
                    </a>
                  ) : (
                    <Button variant="secondary" width="full" disabled>
                      {plan.actionLabel ?? "Choose plan"}
                    </Button>
                  )}
                </div>
              </Flex>
            </Card>
          ))}
        </Flex>
        <Flex className="pricing01-notes" direction="column" align="center">
          <Text tone="muted">{note}</Text>
          {helperHref && <a href={helperHref}>{helperLabel}</a>}
        </Flex>
      </div>
    </section>
  );
}
